#!/bin/sh
# Loads deployment secrets generated by init-secrets.sh, then runs the given command.
# Explicit, non-empty environment variables always win over the secret files.
set -eu

SECRETS_DIR="${SUBBOOST_SECRETS_DIR:-/run/subboost/secrets}"

load_secret() {
  name="$1"
  eval "current=\${$name:-}"
  if [ -z "$current" ] && [ -r "$SECRETS_DIR/$name" ]; then
    value="$(cat "$SECRETS_DIR/$name")"
    export "$name=$value"
  fi
}

load_secret ENCRYPTION_KEY
load_secret JWT_SECRET
load_secret CRON_SECRET
load_secret LOCAL_SETUP_TOKEN

if [ -z "${DATABASE_URL:-}" ]; then
  load_secret POSTGRES_PASSWORD
  if [ -n "${POSTGRES_PASSWORD:-}" ]; then
    DATABASE_URL="$(node -e '
      const e = process.env;
      const user = encodeURIComponent(e.POSTGRES_USER || "subboost");
      const password = encodeURIComponent(e.POSTGRES_PASSWORD);
      const db = encodeURIComponent(e.POSTGRES_DB || "subboost");
      const host = e.POSTGRES_HOST || "db";
      const port = e.POSTGRES_PORT || "5432";
      process.stdout.write(`postgresql://${user}:${password}@${host}:${port}/${db}?schema=public`);
    ')"
    export DATABASE_URL
  fi
  unset POSTGRES_PASSWORD
fi

if [ "${SUBBOOST_ROLE:-app}" = "app" ]; then
  # 首次启动自动创建管理员（见 src/lib/admin-bootstrap.ts）。记录密码来源：
  # 只有自动生成的密码才会打印到日志，docker-compose 中填写的密码不会回显。
  if [ -n "${SUBBOOST_ADMIN_PASSWORD:-}" ]; then
    export SUBBOOST_ADMIN_PASSWORD_SOURCE=environment
  else
    load_secret SUBBOOST_ADMIN_PASSWORD
    if [ -n "${SUBBOOST_ADMIN_PASSWORD:-}" ]; then export SUBBOOST_ADMIN_PASSWORD_SOURCE=generated; fi
  fi
else
  unset SUBBOOST_ADMIN_PASSWORD
fi

exec "$@"
